<?php
namespace Tests\Feature\Ledger; use App\Models\{ChartOfAccount,User}; use App\Services\Ledger\GeneralLedgerService; use DomainException; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class PostingTest extends TestCase { use RefreshDatabase; public function test_balanced_gl_batch_posts(): void {$user=User::factory()->create();$a=ChartOfAccount::create(['code'=>'1000','name'=>'Cash','account_type'=>'ASSET','normal_balance'=>'DEBIT','allow_posting'=>true,'is_active'=>true]);$b=ChartOfAccount::create(['code'=>'3000','name'=>'Capital','account_type'=>'EQUITY','normal_balance'=>'CREDIT','allow_posting'=>true,'is_active'=>true]);$batch=app(GeneralLedgerService::class)->postBatch(['document_number'=>'JV/001','posting_at'=>now(),'source_module'=>'TEST','document_type'=>'JV','posted_by'=>$user->id],[['account_id'=>$a->id,'debit'=>100,'credit'=>0],['account_id'=>$b->id,'debit'=>0,'credit'=>100]]);$this->assertCount(2,$batch->entries);$this->assertDatabaseHas('gl_batches',['document_number'=>'JV/001']);} public function test_unbalanced_gl_batch_is_rejected(): void {$user=User::factory()->create();$a=ChartOfAccount::create(['code'=>'1000','name'=>'Cash','account_type'=>'ASSET','normal_balance'=>'DEBIT','allow_posting'=>true,'is_active'=>true]);$this->expectException(DomainException::class);app(GeneralLedgerService::class)->postBatch(['document_number'=>'JV/002','posting_at'=>now(),'source_module'=>'TEST','document_type'=>'JV','posted_by'=>$user->id],[['account_id'=>$a->id,'debit'=>100,'credit'=>0],['account_id'=>$a->id,'debit'=>0,'credit'=>90]]);} }
